SET NOCOUNT ON;
SELECT TOP (1) CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion')) AS product_major_version, CONVERT(nvarchar(128),SERVERPROPERTY(N'ProductVersion')) AS product_version, CONVERT(nvarchar(128),SERVERPROPERTY(N'Edition')) AS edition, CONVERT(int,SERVERPROPERTY(N'EngineEdition')) AS engine_edition, CONVERT(nvarchar(256),host.host_platform) AS host_platform, CONVERT(bit,COALESCE(HAS_PERMS_BY_NAME(NULL,NULL,N'VIEW SERVER PERFORMANCE STATE'),0)) AS has_required_permission, CONVERT(bit,COALESCE(IS_SRVROLEMEMBER(N'sysadmin'),0)) AS is_sysadmin, CONVERT(nvarchar(40),CONNECTIONPROPERTY(N'auth_scheme')) AS auth_scheme, CONVERT(nvarchar(40),connection_info.encrypt_option) AS encrypt_option, CONVERT(bit,CASE WHEN CONVERT(int,SERVERPROPERTY(N'EngineEdition')) IN (2,3) AND host.host_platform=N'Windows' AND CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion')) BETWEEN 15 AND 17 THEN 1 ELSE 0 END) AS feature_replication, CONVERT(bit,CASE WHEN host.host_platform=N'Windows' THEN 1 ELSE 0 END) AS feature_host_binding FROM sys.dm_os_host_info AS host CROSS JOIN (SELECT TOP (1) encrypt_option FROM sys.dm_exec_connections WHERE session_id=@@SPID) AS connection_info WHERE CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))=16;
